/**
 * Pionier service worker
 * CACHE_VERSION and SHELL query stamps MUST match index.html / pionier-app.js.
 * Generated by scripts/sync-handpan-cache.mjs — do not hand-edit SHELL.
 * Bump handpan-app/APP_VERSION then run: npm run sync:handpan
 *
 * Strategy:
 *  - HTML / navigations: network-first (fallback to cached index offline)
 *  - Versioned shell assets (?v=): network-first when online, cache fallback
 *  - Other same-origin GET: cache-first, then network
 *  - On activate: drop all caches except current CACHE_VERSION
 * Offline readiness: shell + core modules must be listed in SHELL and pre-cached on install.
 */
const CACHE_VERSION = 'pionier-v130';

const SHELL = [
  './',
  './index.html',
  './manifest.webmanifest',
  './icon.svg',
  './atelier.css?v=10',
  './focus-visible.css?v=1',
  './fx-editor.css?v=5',
  './handpan-themes.css?v=2',
  './js/ambient-fx.js?v=12',
  './js/app-state.js?v=1',
  './js/audio-core.js?v=2',
  './js/catch-mode.js?v=4',
  './js/customization-catalog.js?v=7',
  './js/debug.js',
  './js/fx-editor.js?v=9',
  './js/fx.js',
  './js/gesture.js',
  './js/instrument.js',
  './js/instruments/arp-family.js?v=3',
  './js/instruments/handpan-scales.js?v=6',
  './js/instruments/handpan.js?v=11',
  './js/instruments/library-family.js?v=3',
  './js/layout-boot.js?v=69',
  './js/loop-core.js',
  './js/looper.js?v=223',
  './js/note-plus.js?v=3',
  './js/note-sample-bank.js',
  './js/overlay-controller.js?v=23',
  './js/pad-layout.js?v=2',
  './js/phase3-handpan-theme.js?v=1',
  './js/pionier-surface.js?v=146',
  './js/portrait-lock.js?v=1',
  './js/scale-selector.js?v=12',
  './js/settings-panel.js?v=30',
  './js/skin-mandala.js?v=6',
  './js/skin-palette.js?v=2',
  './js/soundscapes.js?v=11',
  './looper-restart-on-record.js?v=2',
  './looper-side-menus.js?v=7',
  './looper.css?v=222',
  './og-pionier-synth.svg',
  './phase1-note-count-guard.js?v=2',
  './pionier-app.js?v=235',
  './pionier-control-layout.css?v=17',
  './pionier-control-layout.js?v=15',
  './pionier-core.js?v=70',
  './pionier.css?v=166',
  './portrait-lock.css?v=1',
  './registerSW.js',
  './registerSW.js?v=2',
  './scale-menu.css?v=19',
  './settings-panel.css?v=19',
  './shell-chrome.css?v=1',
  './system-fonts.css?v=1',
  './theme-light-overlays.css?v=2',
  './topbar-narrow.css?v=6',
  './ui-stability.css?v=6',
  './w3-pan-guard.css?v=1',
  './welcome-screen.css?v=6',
  './welcome-screen.js?v=7',
];

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_VERSION);
    await Promise.all(SHELL.map(async (url) => {
      try {
        const res = await fetch(url, { cache: 'no-cache' });
        if (res && res.ok) await cache.put(url, res);
      } catch (_) {}
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k !== CACHE_VERSION).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

function isDocumentRequest(req, url) {
  if (req.mode === 'navigate') return true;
  if (req.destination === 'document') return true;
  const path = url.pathname;
  return path.endsWith('.html') || path.endsWith('/') || path.endsWith('/handpan-app');
}

function isVersionedAsset(url) {
  return url.search.includes('v=');
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  if (isDocumentRequest(req, url)) {
    event.respondWith(
      fetch(req)
        .then((res) => {
          if (res && res.ok) {
            const copy = res.clone();
            caches.open(CACHE_VERSION).then((c) => c.put(req, copy)).catch(() => {});
          }
          return res;
        })
        .catch(() => caches.match(req).then((r) => r || caches.match('./index.html')))
    );
    return;
  }

  if (isVersionedAsset(url) && (url.pathname.endsWith('.js') || url.pathname.endsWith('.css'))) {
    event.respondWith(
      fetch(req)
        .then((res) => {
          if (res && res.ok) {
            const copy = res.clone();
            caches.open(CACHE_VERSION).then((c) => c.put(req, copy)).catch(() => {});
          }
          return res;
        })
        .catch(() => caches.match(req))
    );
    return;
  }

  event.respondWith(
    caches.match(req).then((cached) => {
      if (cached) return cached;
      return fetch(req).then((res) => {
        if (res && res.status === 200 && res.type !== 'opaque') {
          const copy = res.clone();
          caches.open(CACHE_VERSION).then((c) => c.put(req, copy)).catch(() => {});
        }
        return res;
      });
    })
  );
});
